This example shows how to use the property in a thread-safe manner.

using System.Windows.Forms;
using VectorNav.Devices;

class TestClass
{
	static int Main()
	{
		var vn100 = new Vn100("COM1", 9600);
		vn100.Connect();

		// Get an object reference to the attitude.
		var attObj = vn100.CurrentAttitude;

		// Now if all of our accesses is to the attitude object
		// reference we just obtained, we do not have to worry about
		// the internal thread in the Vn100 object updating the
		// CurrentAttitude property while we are in the middle of
		// using the CurrentAttitude's properties.

		MessageBox.Show("Current yaw angle is " + attObj.Ypr.YawInDegs + ".");

		MessageBox.Show("Current pitch angle is " + attObj.Ypr.PitchInDegs + ".");

		MessageBox.Show("Current roll angle is " + attObj.Ypr.RollInDegs + ".");

		vn100.Disconnect();
	}
}

This example shows how to use the property in a thread-safe manner.

using System.Windows.Forms;
using VectorNav.Devices;

class TestClass
{
	static int Main()
	{
		var vn100 = new Vn100("COM1", 9600);
		vn100.Connect();

		// Get an object reference to the measurements.
		var measObj = vn100.CurrentMeasurements;

		// Now if all of our accesses is to the measurements object
		// reference we just obtained, we do not have to worry about
		// the internal thread in the Vn100 object updating the
		// CurrentMeasurements property while we are in the middle of
		// using the CurrentMeasurements's properties.

		MessageBox.Show("Current x acceleration is " + measObj.Acceleration[0] + ".");

		MessageBox.Show("Current y acceleration is " + measObj.Acceleration[1] + ".");

		MessageBox.Show("Current z acceleration is " + measObj.Acceleration[2] + ".");

		vn100.Disconnect();
	}
}

 This example shows how to establish a connection with a VN-100
 sensor using the  class and get the sensor's current attitude.

using System;
using System.Windows.Forms;
using VectorNav.Devices;

static class Program
{
	[STAThread]
	static void Main()
	{
		// Change the serial port name and baudrate to your specific
		// configuration.
		var vn100 = new Vn100("COM1", 9600);

		vn100.Connect();

		// Get the VN-100 sensor's attitude.
		var attitude = vn100.GetAttitude();

		MessageBox.Show(
			string.Format("Current attitude in Yaw, Pitch, Roll is {0}, {1}, {2}.",
				attitude.Ypr.YawInDegs,
				attitude.Ypr.PitchInDegs,
				attitude.Ypr.RollInDegs));

		vn100.Disconnect();
	}
}


 This example shows how to receive notification when an asynchronous
 message is received from the VN-100 sensor.

using System;
using System.Collections.Generic;
using System.Threading;
using System.Windows.Forms;
using VectorNav.Devices;

static class Program
{
	[STAThread]
	static void Main()
	{
		// Change the serial port name and baudrate to your specific
		// configuration.
		var vn100 = new Vn100("COM1", 9600);

		vn100.Connect();

		// Set the sensor to output YawPitchRoll data at 10 Hz.
		vn100.SetAsyncDataOutputType(Vn100.AsyncOutputType.Ypr, true);
		vn100.SetAsyncDataOutputFreq(10, true);

		// Start listening to asynchronous data received from the VN-100 sensor.
		vn100.AsyncDataReceived += Vn100_AsyncDataReceived;

		// Collect asynchronous data from the VN-100 sensor for 1 second.
		Thread.Sleep(1000);

		// Stop listening to asynchronous data received from the VN-100 sensor.
		vn100.AsyncDataReceived -= Vn100_AsyncDataReceived;

		vn100.Disconnect();

		// Display how many data packets with attitude data we received from the
		// VN-100 sensor.
		MessageBox.Show(
			string.Format("Recieved {0} packets with attitude information.",
			Vn100AttitudeData.Count));
	}

	static void Vn100_AsyncDataReceived(object sender, Vn100.AsyncDataReceivedEventArgs e)
	{
		var compositeData = e.Data;

		// See if this data package includes attitude information from the
		// VN-100 sensor.
		if (compositeData.Attitude != null)
			Vn100AttitudeData.Add(compositeData);
	}

	static readonly List<CompositeData> Vn100AttitudeData = new List<CompositeData>();
}


 The example below shows another common method for accessing attitude
 data from the VN-100 sensor. Instead of receiving an 
 event everytime asynchronous data is received from the sensor, you can
 query the  property which will contain the
 most up-to-date attitude of the sensor. For this property to be updated,
 the sensor must be configured to output a data type that contains attitude
 information.  will also be updated at the
 asynchronous data output frequency the sensor is set to.

using System;
using System.Threading;
using System.Windows.Forms;
using VectorNav.Devices;

static class Program
{
	[STAThread]
	static void Main()
	{
		// Change the serial port name and baudrate to your specific
		// configuration.
		var vn100 = new Vn100("COM1", 9600);

		vn100.Connect();

		// Set the sensor to output YawPitchRoll data at 10 Hz.
		vn100.SetAsyncDataOutputType(Vn100.AsyncOutputType.Ypr, true);
		vn100.SetAsyncDataOutputFreq(10, true);

		// Wait until the Vn100 object receives an asynchronous update with
		// attitude information.
		while (vn100.CurrentAttitude == null)
			Thread.Sleep(10);

		// Be sure to get a copy of the current attitude object to avoid having
		// its values updated while accessing them. For example, if we accessed
		// the values directly in the MessageBox.Show method call as
		// vn100.CurrentAttitude.Ypr.YawInDegs, we stand a slight chance of the
		// vn100 object updating its CurrentAttitude property before the next
		// call to vn100.CurrentAttitude.Ypr.PitchInDegs.
		var currentAttitude = vn100.CurrentAttitude;
		MessageBox.Show(
			string.Format("Current attitude in Yaw, Pitch, Roll is {0}, {1}, {2}.",
				currentAttitude.Ypr.YawInDegs,
				currentAttitude.Ypr.PitchInDegs,
				currentAttitude.Ypr.RollInDegs));

		vn100.Disconnect();
	}
}

